  const rate21 = result.find(r => r.rate === 21);
  const rate9 = result.find(r => r.rate === 9);

  const line1 = invoice.value.lines[0];
  const expectedBase21 = lineTotal(line1) - lineDiscount(line1);
  const expectedVat21 = lineVAT(line1);
  assert.equal(rate21.base, expectedBase21);
  assert.equal(rate21.vat, expectedVat21);

  const line2 = invoice.value.lines[1];
  const expectedBase9 = lineTotal(line2) - lineDiscount(line2);
  const expectedVat9 = lineVAT(line2);
  assert.equal(rate9.base, expectedBase9);
  assert.equal(rate9.vat, expectedVat9);
});

