import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee, dashboard } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals, lineTotal, lineDiscount, lineVAT } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';
import { roundCents } from '../src/money.js';

// Helper to create and issue an invoice for a specific customer
function createAndIssueInvoice(customerId, issueDate, sku = 'DES-HOUR', qty = 1, terms = 'NET30') {
  const draftResult = createInvoice({
    customerId,
    issueDate,
    lines: [{ sku, qty }],
    terms,
  });
  assert.equal(draftResult.ok, true);
  const issuedResult = issueInvoice(draftResult.value, []);
  assert.equal(issuedResult.ok, true);
  return issuedResult.value;
}

test('overdueInvoices returns empty list for empty invoices', () => {
  const result = overdueInvoices([], '2026-10-07');

  assert.equal(result.length, 0);
});

test('overdueInvoices returns empty list when no invoices are overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-10-07', 'DES-HOUR', 1, 'NET30');

  const result = overdueInvoices([invoice], '2026-10-30');

  assert.equal(result.length, 0);
});

test('overdueInvoices includes issued invoices past due date', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-10-01', 'DES-HOUR', 1, 'NET14');

  const result = overdueInvoices([invoice], '2026-10-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, invoice.number);
});

test('overdueInvoices includes partially_paid invoices past due date', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-10-01', 'DES-HOUR', 5, 'NET14');
  const payment = recordPayment(invoice, { amount: 10000, date: '2026-10-08' });
  assert.equal(payment.ok, true);

  const result = overdueInvoices([payment.value], '2026-10-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, invoice.number);
});

test('overdueInvoices excludes draft invoices', () => {
  const draftResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.equal(draftResult.ok, true);

  const result = overdueInvoices([draftResult.value], '2026-10-20');

  assert.equal(result.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-10-01', 'DES-HOUR', 1, 'NET14');
  const totals = invoiceTotals(invoice);
  const payment = recordPayment(invoice, { amount: totals.total, date: '2026-10-08' });
  assert.equal(payment.ok, true);

  const result = overdueInvoices([payment.value], '2026-10-20');

  assert.equal(result.length, 0);
});

test('overdueInvoices excludes invoices with dueDate on or after asOf', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET30');

  const result = overdueInvoices([invoice], '2026-10-01');

  assert.equal(result.length, 0);
});

test('overdueInvoices includes invoices with dueDate before asOf', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET30');

  const result = overdueInvoices([invoice], '2026-10-02');

  assert.equal(result.length, 1);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');

  const result = overdueInvoices([invoice], '2026-09-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 5);
});

test('overdueInvoices includes correct fields in result', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');

  const result = overdueInvoices([invoice], '2026-09-20');

  assert.equal(result.length, 1);
  const item = result[0];
  assert.equal(typeof item.number, 'string');
  assert.equal(item.number, invoice.number);
  assert.equal(typeof item.customerId, 'string');
  assert.equal(item.customerId, 'C-001');
  assert.equal(typeof item.dueDate, 'string');
  assert.equal(item.dueDate, invoice.dueDate);
  assert.equal(typeof item.daysOverdue, 'number');
  assert.equal(typeof item.due, 'number');
});

test('overdueInvoices calculates due using balanceDue', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');
  const expectedDue = balanceDue(invoice);

  const result = overdueInvoices([invoice], '2026-09-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].due, expectedDue);
});

test('overdueInvoices with partial payment shows reduced due', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 2, 'NET14');
  const payment = recordPayment(invoice, { amount: 5000, date: '2026-09-08' });
  assert.equal(payment.ok, true);
  const expectedDue = balanceDue(payment.value);

  const result = overdueInvoices([payment.value], '2026-09-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].due, expectedDue);
  assert.equal(result[0].due < invoiceTotals(invoice).total, true);
});

test('overdueInvoices sorts by daysOverdue descending (most overdue first)', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2026-08-01', 'DES-HOUR', 1, 'NET14');
  const invoice2 = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');
  const invoice3 = createAndIssueInvoice('C-001', '2026-09-15', 'DES-HOUR', 1, 'NET14');

  const result = overdueInvoices([invoice3, invoice1, invoice2], '2026-10-05');

  assert.equal(result.length, 3);
  assert.equal(result[0].number, invoice1.number);
  assert.equal(result[1].number, invoice2.number);
  assert.equal(result[2].number, invoice3.number);
});

test('overdueInvoices with same daysOverdue maintains relative order', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');
  const invoice2 = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');

  const result = overdueInvoices([invoice1, invoice2], '2026-09-20');

  assert.equal(result.length, 2);
  assert.equal(result[0].daysOverdue, result[1].daysOverdue);
});

test('overdueInvoices handles mixed statuses correctly', () => {
  const issued = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');
  const paid = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');
  const paidResult = recordPayment(paid, { amount: invoiceTotals(paid).total, date: '2026-09-08' });
  assert.equal(paidResult.ok, true);

  const result = overdueInvoices([issued, paidResult.value], '2026-09-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.number);
});

test('overdueInvoices includes multiple customers', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');
  const invoice2 = createAndIssueInvoice('C-002', '2026-09-05', 'DES-HOUR', 1, 'NET14');

  const result = overdueInvoices([invoice1, invoice2], '2026-09-25');

  assert.equal(result.length, 2);
});

test('overdueInvoices handles NET14 terms correctly', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');

  const beforeDueResult = overdueInvoices([invoice], '2026-09-14');
  const onDueResult = overdueInvoices([invoice], '2026-09-15');
  const afterDueResult = overdueInvoices([invoice], '2026-09-16');

  assert.equal(beforeDueResult.length, 0);
  assert.equal(onDueResult.length, 0);
  assert.equal(afterDueResult.length, 1);
});

test('overdueInvoices handles NET30 terms correctly', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET30');

  const beforeDueResult = overdueInvoices([invoice], '2026-09-30');
  const onDueResult = overdueInvoices([invoice], '2026-10-01');
  const afterDueResult = overdueInvoices([invoice], '2026-10-02');

  assert.equal(beforeDueResult.length, 0);
  assert.equal(onDueResult.length, 0);
  assert.equal(afterDueResult.length, 1);
});

test('overdueInvoices handles EOM terms correctly', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-15', 'DES-HOUR', 1, 'EOM');

  const beforeDueResult = overdueInvoices([invoice], '2026-09-30');
  const onDueResult = overdueInvoices([invoice], '2026-10-01');
  const afterDueResult = overdueInvoices([invoice], '2026-10-02');

  assert.equal(beforeDueResult.length, 0);
  assert.equal(onDueResult.length, 1);
  assert.equal(afterDueResult.length, 1);
});

test('overdueInvoices does not mutate input array', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');
  const invoices = [invoice];
  const invoicesCopy = JSON.parse(JSON.stringify(invoices));

  overdueInvoices(invoices, '2026-09-20');

  assert.deepEqual(invoices, invoicesCopy);
});

test('overdueInvoices does not mutate individual invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  overdueInvoices([invoice], '2026-09-20');

  assert.deepEqual(invoice, invoiceCopy);
});

test('overdueInvoices with large number of invoices', () => {
  const invoices = [];
  for (let i = 0; i < 100; i++) {
    const daysAgo = Math.floor(Math.random() * 100);
    const date = '2026-' + String(10 - Math.floor(daysAgo / 30)).padStart(2, '0') + '-' + String(7 - (daysAgo % 30)).padStart(2, '0');
    try {
      invoices.push(createAndIssueInvoice('C-001', date, 'DES-HOUR', 1, 'NET14'));
    } catch {
      // Skip invalid dates
    }
  }

  const result = overdueInvoices(invoices, '2026-10-07');

  assert.equal(result.length > 0, true);
  // Verify sorting
  for (let i = 0; i < result.length - 1; i++) {
    assert.equal(result[i].daysOverdue >= result[i + 1].daysOverdue, true);
  }
});

test('overdueInvoices with discounted invoices', () => {
  const draftResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
    terms: 'NET14',
  });
  assert.equal(draftResult.ok, true);
  const invoice = issueInvoice(draftResult.value, []);
  assert.equal(invoice.ok, true);

  const result = overdueInvoices([invoice.value], '2026-09-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].due, balanceDue(invoice.value));
});

test('overdueInvoices with VAT-exempt invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01', 'WORKSHOP-DAY', 1, 'NET14');

  const result = overdueInvoices([invoice], '2026-09-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].due, balanceDue(invoice));
});

test('overdueInvoices across year boundary', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-12-01', 'DES-HOUR', 1, 'NET30');
  const invoice2 = createAndIssueInvoice('C-001', '2026-01-01', 'DES-HOUR', 1, 'NET30');

  const result = overdueInvoices([invoice1, invoice2], '2026-02-05');

  assert.equal(result.length, 2);
  assert.equal(result[0].number, invoice1.number);
});

test('overdueInvoices maintains daysOverdue calculation accuracy', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2026-08-01', 'DES-HOUR', 1, 'NET14');
  const invoice2 = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');

  const result = overdueInvoices([invoice1, invoice2], '2026-10-05');

  assert.equal(result.length, 2);
  assert.equal(result[0].daysOverdue, 51);
  assert.equal(result[1].daysOverdue, 20);
});

test('vatSummary returns empty list for empty invoices', () => {
  const result = vatSummary([]);

  assert.equal(result.length, 0);
});

test('vatSummary returns empty list when no eligible invoices', () => {
  const draftResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
