test('vatSummary includes partially_paid invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-10-01', 'DES-HOUR', 1);
  const payment = recordPayment(invoice, { amount: 1000, date: '2026-10-08' });
  assert.equal(payment.ok, true);

  const result = vatSummary([payment.value]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
});

test('vatSummary includes paid invoices', () => {
