  assert.equal(typeof item.base, 'number');
  assert.equal(typeof item.vat, 'number');
  assert.equal(item.rate, 21);
});

test('vatSummary aggregates multiple lines with same VAT rate', () => {
  const draftResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'DEV-HOUR', qty: 2 },
    ],
  });
