  const invoice = issueInvoice(draftResult.value, []);
  assert.equal(invoice.ok, true);

  const result = vatSummary([invoice.value]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  const expectedBase = lineTotal(invoice.value.lines[0]) - lineDiscount(invoice.value.lines[0]) +
                       lineTotal(invoice.value.lines[1]) - lineDiscount(invoice.value.lines[1]);
  const expectedVat = lineVAT(invoice.value.lines[0]) + lineVAT(invoice.value.lines[1]);
  assert.equal(result[0].base, expectedBase);
  assert.equal(result[0].vat, expectedVat);
});

